-- Isolamento por empresa (multiempresa): company_id nas tabelas de conteudo.
-- Dados existentes pertencem a empresa 1 (DEFAULT). Depois do backfill o DEFAULT da coluna e removido:
-- insert sem empresa (fora dos models base) falha em vez de cair silenciosamente na empresa 1.
-- Rollback: ALTER TABLE <t> DROP FOREIGN KEY fk_<t>_company, DROP INDEX idx_<t>_company, DROP COLUMN company_id;

ALTER TABLE `calendar_event_attachments` ADD COLUMN `company_id` BIGINT NOT NULL DEFAULT 1 AFTER `id`, ADD KEY `idx_calendar_event_attachments_company` (`company_id`), ADD CONSTRAINT `fk_calendar_event_attachments_company` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`);
